"""Refine the original 26 drafts without overwriting the expanded work items."""
from pathlib import Path
import re

ROOT=Path(__file__).resolve().parents[2]
DRAFTS=ROOT/'docs/case-studies/issue-29/issues'
CASE='https://github.com/link-assistant/web-search/blob/issue-29-03fe983c7d11/docs/case-studies/issue-29/README.md'
DETAILS={
'WS-01':('Extend current engine options and merger with shared validation/envelope fixtures, retaining canonical dedupe and provider receipts across queries.', 'Bound total provider×query calls and cancellation through existing transport. Objective-only requests need injectable query planning or an explicit deterministic fallback.', 'Objective-only/query-only/invalid input, duplicate URLs, all-provider failure, finite fan-out, cancellation, and legacy wrappers.'),
'WS-02':('Use one matcher before provider calls and after merging: provider operators cannot be the enforcement boundary.', 'Treat unknown publication dates explicitly rather than equating modified/capture timestamps with publication.', 'IDN/apex/subdomain/suffix/path boundaries, overlapping include/exclude, invalid/unknown dates, and JS/Rust equivalence.'),
'WS-03':('Inspect provider descriptors before adding country mappings and separate country bias from language.', 'Use data-driven code tables, preserve region/language aliases, and report unsupported provider mappings.', 'Country-only/language-only requests, uppercase/gb normalization, unsupported provider, and generated parameters.'),
'WS-04':('Reuse capture batch/ranker interfaces after merge with optional bounded fetching.', 'Allocate budgets deterministically across deduplicated results and preserve original sources/fetch receipts.', 'Zero/tiny caps, Unicode, duplicate URLs, mixed failures, cancellation, and fallback snippets within the total cap.'),
'WS-05':('Initialize optional models lazily using injected adapters and shared preprocessing fixtures.', 'Compare @huggingface/transformers and fastembed::TextRerank, recording model/version and batch limits without default downloads.', 'Stable ties, topK boundaries, load failure, multilingual candidates, cancellation, and preserved provenance.'),
'WS-06':('Resolve modes through shared configurable preset data and report effective options.', 'Define turbo cache-miss behavior explicitly and separate model selection from measured quality: WS-41 owns evaluation.', 'Cache hit/miss, override precedence, legacy versus GA defaults, invalid modes, and absent optional model.'),
'WS-07':('Reuse WC-04 receipts and scope query-cache keys by policy/locale/mode/caller/transport.', 'Report stale fallback and implement GA min age 600 and disable_cache_fallback. A zero-age force-live option is a named local extension.', 'Exact age boundary, fallback enabled/disabled, isolated keys, concurrent refresh, and publication versus capture date.'),
'WS-08':('Extend current registry/merger with typed image descriptors, adding adapters incrementally from fixtures.', 'Preserve supplied attribution/license and keep dimension probes optional and policy/byte bounded via WC-10.', 'Missing dimensions/source pages, lazy/relative URLs, duplicates, provider failure, and keyword/objective modes.'),
'WS-09':('Separate natural-language objective planning from source adapters and validate supported source filters.', 'Preserve ambiguous entities with stable IDs/canonical websites and provenance rather than deduping by name alone.', 'Same-name distinct entities, pagination, match_limit boundaries, unavailable licensed source, and stable ranking.'),
'WS-10':('Define shared schemas first and mount GA adapters without removing existing routes.', 'Advertise only implemented routes in OpenAPI, with image routing after WS-08 and Extract proxy against WC-11.', 'Positive/negative quickstart requests, unavailable capture backend, unknown fields, auth, 422/429, and JS/Rust parity.'),
'WS-11':('Use official MCP SDKs and generated tool schemas: outbound research tools are WS-25 and Task tools WS-30.', 'Validate header/query/tool overrides once with explicit precedence and forward caller scope into web_fetch.', 'SDK tools/list/call, stdio/HTTP, invalid input, cancellation, budgets, and typed partial failures.'),
'WS-12':('Extend current installed CLI/parser tests with direct typed library/service delegation.', 'Keep async and account command families in WS-44 and mount MCP subcommands after WS-11.', 'Legacy positional search, repeated queries, stdin, invalid combinations, JSON stdout/diagnostics stderr, and exit codes.'),
'WS-13':('Implement run/store/worker abstraction with in-memory fixtures and optional durable SQLite.', 'Recover queued/running work after restart with scope, finite concurrency, typed failure, cancellation, and retention. WS-19/20/21 own protocols/groups.', 'All state transitions, cancellation races, restart, blocking-result timeout, input round-trip, overload, and expiry.'),
'WS-14':('Execute Task research through caller-configured model adapters: plan bounded retrieval, extract evidence, and synthesize text/JSON with field-level basis.', 'Keep evidence/provenance explicit and reject invented citation URLs. WS-24 handles specs/interactions and WS-22/23 format Responses/Chat.', 'Stub research loop, unsupported backend, budget exhaustion, invalid JSON, uncited fields, and partial sources.'),
'WS-15':('Implement GA event-stream Monitor CRUD/stats/trigger/schedule with durable checkpoints and paginated JSON events.', 'Deduplicate material detections, not just URLs, and prevent overlapping scheduled/manual runs. WS-29 owns snapshot/follow-up work.', 'Fake-clock no-change/detection/failure, missed schedule recovery, pagination, update/cancel, and signed notifications.'),
'WS-16':('Implement core discovery/matching on stable candidates with attributable condition basis and partial results.', 'Use WS-24 inference through POST /v1beta/findall/ingest and GET run/schema retrieval. WS-27/28 own enrichment and lifecycle controls.', 'Finite generator budget, matched/unmatched/unknown condition evidence, ambiguous dedupe, partial result, and schema.'),
'WS-17':('Validate session/client hints and operation/SKU counters through shared envelopes.', 'Separate usage from billing WS-34 and configurable per-key limiting from provider retry behavior.', 'Length limits, echo/generation, partial-failure usage, fake-clock 429/recovery, key isolation, and limiter disabled.'),
'WS-18':('Implement caller-scoped Memory query relevance/recent ordering and retrieve/evict/clear over stored results.', 'Evict/clear affects memory visibility without deleting underlying runs. WS-40 owns migration guides and disabled retention is explicit.', 'Ranked/recent retrieval, cross-scope isolation, preserved runs after clear, missing IDs, restart, and expiry.'),
'WC-01':('Add a pure passage scorer over existing conversion output with shared tokenization/scoring fixtures.', 'Compare BM25/lead/optional embeddings using WC-12 and define empty-document/no-objective/tiny-cap behavior.', 'Headings/tables/long passages, multilingual tokens, stable ties, Unicode/no-word-boundary cases, and exact budgets.'),
'WC-02':('Implement one batch engine over current conversion/transport interfaces: WC-11 owns its versioned wrapper.', 'Preserve URL-to-input association, bound total/per-host work, and separate excerpt budgets from full_content caps.', 'Mixed success/404/timeout/blocked/binary, duplicates, cancellation, zero budgets, and full_content options.'),
'WC-03':('Keep publication/modification/capture metadata distinct with source attribution and confidence.', 'Unknown publication stays null. Last-Modified or URL guesses cannot silently become confirmed publication dates.', 'Contradictory/malformed/future metadata, timezones, unknown dates, canonical/language fields, and parity.'),
'WC-04':('Extend CaptureStore/CachedTransport policy resolution while preserving default/caller-owned behavior.', 'GA max_age_seconds minimum is 600, with timeout_seconds and disable_cache_fallback. Force-live/cache-bypass are separate local extensions.', 'Age boundary, stale fallback on/off, live failure, conditional revalidation, cache scope, and refresh dedupe.'),
'WC-05':('Reuse cached robots matching and per-origin scheduling with documented versioned user agent.', 'Publish operator IP-list templates instead of asserting project-wide static IPs, and document unavailable robots/legacy behavior.', 'Allow/disallow precedence, agent groups, robots refresh/redirects, host delay/concurrency, and explicit opt-out.'),
'WC-06':('Route by type/visible-content heuristics into existing browser/PDF modules and record the path.', 'One end-to-end deadline and WC-10 limits cover static/browser/converter fallback and cleanup.', 'SPA/static/PDF, wrong type, encrypted/malformed PDF, finite oversized input, browser failure, and cancellation.'),
'WC-07':('Add pure HTML image extraction plus optional bounded header probes, separate from screenshots.', 'Resolve base/relative/lazy URLs and preserve source/alt/attribution without fetching whole images.', 'srcset/metadata/duplicates/data URLs, corrupt header, missing size, redirect, and probe budget.'),
'WC-08':('Generate web_fetch schemas from WC-11 and delegate CLI JSON to WC-02.', 'WC-09 owns authenticated capture, and tool wrappers preserve errors/budgets/full_content across formats.', 'SDK schema/call, mixed URL failures, CLI stdout/stderr, invalid args, and JS/Rust parity.'),
}
