for path in DRAFTS.glob('*.md'):
 text=path.read_text(); id_=re.search(r'^id: (.+)$',text,re.M)[1]
 if id_ not in DETAILS: continue
 text=text.split('\n## Implementation follow-through')[0]
 if id_ in REPLACE:
  title,deps,summary,scope=REPLACE[id_]
  text=re.sub(r'^title: .*$', 'title: '+title,text,flags=re.M)
  text=re.sub(r'^depends_on: .*$', 'depends_on: '+deps,text,flags=re.M)
  text=re.sub(r'## Summary\n.*?(?=## Acceptance criteria)', '## Summary\n\n'+summary+'\n\n## Scope\n\n'+'\n'.join('- '+s for s in scope)+'\n\n',text,flags=re.S)
  # Old criteria on these bundles assert deferred features. Replace with focused follow-through criteria.
  text=re.sub(r'## Acceptance criteria\n.*?(?=\n## References|\Z)', '## Acceptance criteria\n\n- '+DETAILS[id_][2]+'\n- Existing unit/integration and JS/Rust parity checks pass.\n',text,flags=re.S)
 text=text.replace('@xenova/transformers','@huggingface/transformers').replace('https://github.com/link-assistant/web-search/blob/main/docs/case-studies/issue-29/README.md',CASE)
 if id_=='WC-04':
  text=text.replace('disable_cached_content','disable_cache_fallback')
  text=text.replace('- `max_age_seconds: 0` forces a live fetch; otherwise serve the cached\n  capture when `now - capturedAt <= max_age_seconds`.','- GA `max_age_seconds` has minimum 600; serve cache within the age budget and attempt live refresh otherwise. Force-live is a separately documented local extension.')
  text=text.replace('- `disable_cache_fallback: true` bypasses the cache entirely; `timeout_seconds`\n  caps the live fetch and falls back to cache when allowed.','- `disable_cache_fallback: true` returns an error when live refresh fails; false permits stale fallback. `timeout_seconds` bounds live work.')
 if id_=='WC-03':
  text=text.replace('HTTP `Last-Modified`, URL path patterns (`/2026/09/18/`).','Publication remains unknown when only HTTP `Last-Modified` or URL date patterns are available; preserve those as modification/heuristic metadata.')
 if id_=='WS-06':
  text=text.replace('as presets plus an evaluation harness','as configurable pipeline presets')
  text=re.sub(r'- `experiments/search-eval/` harness:.*?(?=\n- Default)', '- Evaluation and benchmark comparisons are tracked separately in WS-41.',text,flags=re.S)
  text=text.replace('- Harness runs offline on recorded fixtures in CI.','- Cache-miss policy and effective mode options have offline fixture tests.')
 if id_=='WS-10':
  text=text.replace('depends_on: [WS-02, WS-03, web-capture WC-02]','depends_on: [WS-02, WS-03, WS-04, WS-08, WC-11]')
  text=text.replace('https://docs.parallel.ai/openapi.json','https://docs.parallel.ai/public-openapi.json')
 if id_=='WS-12': text=text.replace('depends_on: [WS-10]','depends_on: [WS-09, WS-10, WS-11]')
 if id_=='WC-02': text=text.replace('depends_on: [WC-01, WC-03, WC-04]','depends_on: [WC-01, WC-03, WC-04, WC-10]')
 if id_=='WC-06': text=text.replace('depends_on: [WC-02]','depends_on: [WC-02, WC-10]')
 if id_=='WS-07': text=text.replace('depends_on: [WS-04, web-capture WC-04]','depends_on: [WS-02, WS-04, WC-04]')
 steps=DETAILS[id_]
 text+='\n\n## Implementation follow-through\n\n1. '+steps[0]+'\n2. '+steps[1]+'\n\n## Additional verification\n\n- '+steps[2]+'\n- Use mocks/local servers with finite test deadlines, update types and examples, and keep live comparisons opt-in.\n'
 text+='\n## Planning references\n\n- [Case study and verified source snapshot]('+CASE+').\n- Original requirement: https://github.com/link-assistant/web-search/issues/29\n'
 path.write_text(text)
print('Refined 26 original drafts and corrected product ownership/contracts.')
